import type { CoverageExtract } from './coverage'
import type { AttributeCell, ValueOverlay } from './api'
import { emptyExtract } from './coverage'
import type { OverviewExtract } from './overview'
import { emptyOverview } from './overview'
import type {
  AttributeGroup,
  AttributeOwner,
  ChangelogPayload,
  Market,
  ProductDetail,
  ProductSummary,
  SizeRow,
} from './api'
import { MARKETS } from './api'
import { DEMO_PRODUCTS } from './productFixtures'

/**
 * Loads the real-data demo extract from `public/demo/`, generated by
 * `scripts/build_demo_data.py` from the Omnitron exports, the Looker control
 * table and the Akinon EE table.
 *
 * This exists so the app can be judged at real scale — thousands of products,
 * real names, real per-market liveness, real gaps — before the importer and
 * API are written. When they land, these two functions are what get replaced
 * by `useApi` calls; nothing else changes.
 *
 * Falls back to the small hand-built fixture if the extract isn't present, so
 * a fresh clone still renders without anyone having to run the generator.
 */

let productsCache: Promise<ProductSummary[]> | null = null
let detailsCache: Promise<Record<string, DemoDetail>> | null = null

interface DemoDetail {
  /** attribute key -> market (`*` when not market-keyed) -> value.
   *  The whole matrix, so the page renders the registry rather than a
   *  list hardcoded in this file. */
  attributes?: Record<string, Record<string, string>>
  /** One row per SKU, with its own stock and price per market. Price and
   *  stock are size-level facts; the ModelColor rollup hides that four of
   *  eleven sizes are on zero. */
  sizes?: {
    label: string
    sku: string
    ean?: string | null
    stock: Partial<Record<Market, number>>
    price: Partial<Record<Market, string>>
  }[]
  /** attribute key -> markets whose sizes disagree. Emitted by the generator
   *  so the matrix never prints one size's value as the option's. */
  perSize?: Record<string, string[]>
  /** attribute key -> market -> English confidence, only for confident
   *  calls (>= 0.90). Computed at generation by the language rule; the
   *  frontend only renders it, per the one-implementation decision. */
  en?: Record<string, Record<string, number>>
  photos?: string[]
  pl: Record<string, string | number>
  stock: number
  markets: Record<
    string,
    {
      name: string
      detail: string
      desc?: string
      price: string
      stock: number
      /** Confidence the value is English, 0 when it isn't. From the generator. */
      nameEn?: number
      detailEn?: number
    }
  >
}

/**
 * Fetch one of the generated extract files.
 *
 * Two things this guards that the previous inline fetches did not.
 *
 * **Absolute path.** They used `demo/products.json`, relative — which on
 * `/products/L3558.132` resolves to `/products/L3558.132/demo/products.json`.
 *
 * **Content type.** That wrong path does not 404: the SPA catch-all serves
 * index.html for anything it does not recognise, with a 200. So `r.ok` passed,
 * `r.json()` threw on the HTML, and the caller's `.catch()` quietly swapped in
 * the hand-built fixture. The panel then showed 28 invented products, or one
 * real URL rendering a different product's data entirely — and looked like it
 * was working. Whether you saw real data depended on which page you loaded
 * first, because the caches below are module-level.
 */
async function loadExtract<T>(name: string, fallback: T): Promise<T> {
  try {
    // `cache: 'no-cache'` — revalidate every time, never trust stored
    // freshness.
    //
    // These files are regenerated under URLs that never change: changelog.json
    // on every container boot, coverage.json whenever the extract is rebuilt.
    // A plain fetch lets the browser reuse a stored copy without asking, and
    // because the server sent no lifetime it invents one from the file's age
    // — so a six-day-old artefact bought roughly fourteen hours of silence
    // after it had been replaced. That is how the panel showed v0.24.1 in the
    // sidebar, from the API, and 0.23.0 on What's New, from cache.
    //
    // 0.24.1 set `no-cache` on the server, which was necessary and not
    // sufficient: a response already stored under the old headers keeps its
    // invented lifetime, so the fix could not reach the browsers that had the
    // problem. Asking here works on those too.
    //
    // Not `no-store`: this must still 304. coverage.json runs to megabytes and
    // re-downloading it on every navigation would be a worse bug than the one
    // being fixed.
    const res = await fetch(`/demo/${name}`, { cache: 'no-cache' })
    if (!res.ok) return fallback
    const type = res.headers.get('content-type') ?? ''
    if (!type.includes('json')) return fallback
    return (await res.json()) as T
  } catch {
    return fallback
  }
}

/** When the extract was built, and when the shops were last read.
 *
 *  Its own file because `products.json` is a bare array of megabytes: a live
 *  count needs its `as of` rendered beside it, and neither wrapping the array
 *  nor stamping every row is worth that. Absent on extracts built before the
 *  storefront stage, which is why every field is optional and the strip falls
 *  back to saying nothing rather than to saying "never".
 */
export interface ExtractMeta {
  generatedAt?: string
  observedAt?: string | null
  observedMarkets?: string[]
}

let metaCache: Promise<ExtractMeta> | null = null

export function loadMeta(): Promise<ExtractMeta> {
  if (!metaCache) metaCache = loadExtract<ExtractMeta>('meta.json', {})
  return metaCache
}

export function loadProducts(): Promise<ProductSummary[]> {
  if (!productsCache) {
    productsCache = loadExtract<ProductSummary[]>('products.json', DEMO_PRODUCTS)
  }
  return productsCache
}

function loadDetails(): Promise<Record<string, DemoDetail>> {
  if (!detailsCache) {
    detailsCache = loadExtract<Record<string, DemoDetail>>('details.json', {})
  }
  return detailsCache
}

/** The attribute registry, emitted by the generator alongside the extract.
 *
 *  The matrix used to be a list written out by hand in this file, which meant
 *  the page could only ever show attributes someone had remembered to add —
 *  and three rows were pinned to "missing" no matter what the database held.
 *  `fit` and `collar_type` were two of them, with 13,339 real values between
 *  them. Reading the registry instead means a new attribute appears on the
 *  page by virtue of existing.
 *
 *  Empty on failure: the matrix renders nothing rather than the page failing,
 *  and the product header still tells you what you are looking at. */
let registryCache: Promise<AttributeMeta[]> | null = null

export interface AttributeMeta {
  key: string
  label: string
  dataType: string
  group: string
  order: number
  owner: AttributeOwner
  perMarket: boolean
  longText: boolean
  gatesGoLive: boolean
  appliesWhenSubcategory: string | null
}

export interface TermLabel {
  label: string
  translated: boolean
  ambiguous?: boolean
}

/** attribute key -> baseline (Turkish) term -> market -> localised label. */
export type LabelMap = Record<string, Record<string, Record<string, TermLabel>>>

let labelsCache: Promise<LabelMap> | null = null

function loadLabels(): Promise<LabelMap> {
  if (!labelsCache) labelsCache = loadExtract<LabelMap>('labels.json', {})
  return labelsCache
}

function loadRegistry(): Promise<AttributeMeta[]> {
  if (!registryCache) {
    registryCache = loadExtract<AttributeMeta[]>('attributes.json', [])
  }
  return registryCache
}

let coverageCache: Promise<CoverageExtract> | null = null

/**
 * The coverage extract — attribute presence per option, plus the registry, the
 * issue vocabulary and the preset profiles.
 *
 * Presence only, never values, which is what keeps a file covering the whole
 * catalogue small enough to load whole and evaluate on every keystroke.
 *
 * An empty extract on failure rather than a throw: the page then says it has
 * no data and why. Falling back to a fixture would be worse here than on any
 * other page — a coverage number that silently describes 28 invented products
 * is indistinguishable from one that describes the catalogue, and acting on it
 * is the entire purpose of the page.
 */
export function loadCoverage(): Promise<CoverageExtract> {
  if (!coverageCache) {
    coverageCache = loadExtract<CoverageExtract>('coverage.json', emptyExtract())
  }
  return coverageCache
}

let overviewCache: Promise<OverviewExtract> | null = null

/**
 * The go-live funnel.
 *
 * Falls back to an empty extract rather than a fixture, like coverage: a
 * convincing invented funnel is worse than a page that says nothing has been
 * generated, because only one of them sends somebody to fix it.
 */
export function loadOverview(): Promise<OverviewExtract> {
  if (!overviewCache) {
    overviewCache = loadExtract<OverviewExtract>('overview.json', emptyOverview())
  }
  return overviewCache
}

let changelogCache: Promise<ChangelogPayload> | null = null

/**
 * Release notes for the What's new page.
 *
 * Generated by `python -m pim_studio.changelog`, which parses CHANGELOG.md
 * with the same code a future `/api/changelog` endpoint will call — so the
 * page keeps working unchanged when the API layer lands, and there is never a
 * second parser to keep in step.
 *
 * An empty payload on failure rather than a throw: the page says "no release
 * notes yet", which is honest and non-blocking, where an unhandled rejection
 * would take out a page reached from the topbar bell.
 */
export function loadChangelog(): Promise<ChangelogPayload> {
  if (!changelogCache) {
    changelogCache = loadExtract<ChangelogPayload>('changelog.json', {
      current_version: '',
      entries: [],
    })
  }
  return changelogCache
}

const clean = (v: unknown): string => {
  const s = String(v ?? '').trim()
  return s === '0.0' || s === '0' ? '' : s
}

/** Wording for the inspector when a value reads as English.
 *
 *  Detection itself happens at ingest, not here: the generator runs a proper
 *  constrained language detector and emits a confidence per field, so there is
 *  one implementation rather than a Python one and a TypeScript one that have
 *  to be kept in step by hand. */
function englishReason(market: Market, confidence: number): string {
  const strength = confidence >= 0.9 ? 'strongly' : confidence >= 0.7 ? '' : 'weakly'
  return `Language check: this ${market} value ${strength} reads as English (${Math.round(
    confidence * 100,
  )}% confidence). Likely the EN source was pasted into the ${market} field.`.replace('  ', ' ')
}

type OverlayRowLike = ValueOverlay['rows'][number]

/** What the page calls a source, from what the row calls one. */
const SOURCE_LABEL: Record<string, string> = {
  omnitron_api: 'omnitron sync',
  omnitron_export: 'omnitron export',
  human: 'set in the panel',
  masterdata: 'masterdata file',
  brandlibrary: 'brand library',
}

/**
 * Lay one overlay row over a cell built from the extract. The database's
 * lifecycle state replaces the extract's — which was only ever "is the market
 * live", not "what happened to this value" — and the person who last set it
 * is named. A cell with no overlay row is left exactly as the extract had it.
 */
function withOverlay(
  cell: AttributeCell,
  row: OverlayRowLike | undefined,
  writable: boolean | undefined,
  proposal?: { value: string; why: string | null } | undefined,
): AttributeCell {
  const out: AttributeCell = writable === undefined ? { ...cell } : { ...cell, writable }
  // A proposal is independent of the overlay row: a cell can carry a
  // suggestion whether or not the database has anything else to say about it,
  // and a cell the extract shows as empty is exactly where one is wanted.
  if (proposal && cell.state !== 'na') {
    out.proposedValue = proposal.value
    if (proposal.why) out.proposedWhy = proposal.why
  }
  if (!row || cell.state === 'na') return out
  out.state = row.state
  out.source = SOURCE_LABEL[row.sourceKind] ?? row.sourceKind
  // Shown for human values too, not just synced ones. For anything written
  // before the panel stamped `updated_by` — a conflict decision, say — the
  // source_ref is the *only* record of who decided it, and suppressing it as
  // redundant left those cells crediting nobody at all.
  if (row.sourceRef) out.sourceDetail = row.sourceRef
  if (row.updatedBy) out.changedBy = row.updatedBy
  if (row.updatedAt) out.changedAt = row.updatedAt.slice(0, 16).replace('T', ' ')
  return out
}

/**
 * Builds a Product Detail view from the demo extract.
 *
 * The extract carries what the exports actually expose — per-market name,
 * detail, price and stock, plus the PL-side category, season, comment and
 * image. Attributes the exports don't carry (fit, collar, composition) are
 * rendered as genuinely missing rather than invented, because the point of
 * looking at real data is to see the real holes.
 */
export async function loadProductDetail(
  modelColor: string,
  overlay: ValueOverlay | null = null,
): Promise<ProductDetail | null> {
  const [products, details, registry, labels] = await Promise.all([
    loadProducts(),
    loadDetails(),
    loadRegistry(),
    loadLabels(),
  ])
  const summary = products.find((p) => p.modelColor === modelColor)
  if (!summary) return null
  const d = details[modelColor]
  // Every product should have a record. If one ever doesn't, the matrix must
  // not render its fields as `missing` — that asserts the value is absent
  // upstream when the truth is that we didn't load it, and it contradicts
  // what the list page says about the same product.
  const detailLoaded = d !== undefined

  // The matrix is the registry, not a list maintained here. Anything seeded
  // into `attributes` shows up; anything with values shows them. The previous
  // hardcoded version listed 15 rows and pinned `composition`, `fit` and
  // `collar_type` to "missing" unconditionally — `fit` alone has 7,146 values,
  // so the page was asserting an absence the database disagreed with.
  const attrValues: Record<string, Record<string, string>> = { ...(d?.attributes ?? {}) }

  // The live overlay wins over the extract, cell by cell. It is the same
  // database the extract was built from, read now instead of last night, so
  // a value set this afternoon shows this afternoon. Merged into the raw
  // values *before* `cellFor` so a dropdown term still gets its market label.
  const overlayRows = new Map<string, OverlayRowLike>()
  const writable = new Set<string>()
  if (overlay) {
    for (const row of overlay.rows) {
      overlayRows.set(`${row.attribute}\u0000${row.market}`, row)
      if (row.value !== null) {
        attrValues[row.attribute] = { ...(attrValues[row.attribute] ?? {}), [row.market]: row.value }
      }
    }
    for (const w of overlay.writable) writable.add(`${w.attribute}\u0000${w.market}`)
  }
  const overlayFor = (key: string, market: string) => overlayRows.get(`${key}\u0000${market}`)

  const proposalRows = new Map<string, { value: string; why: string | null }>()
  if (overlay) {
    for (const p of overlay.proposals ?? []) {
      proposalRows.set(`${p.attribute}\u0000${p.market}`, { value: p.value, why: p.why })
    }
  }
  const proposalFor = (key: string, market: string) =>
    proposalRows.get(`${key}\u0000${market}`)

  const isCode = (meta: AttributeMeta) =>
    meta.dataType === 'number' ||
    /(_code|_sezon|^ean$)/.test(meta.key)

  // A wallet has no sleeve type. The registry says which attributes apply to
  // which sub-categories, and an attribute that does not apply is `na` — never
  // `missing`, which would put it in someone's queue to go and fill in.
  const applies = (meta: AttributeMeta) => {
    if (!meta.appliesWhenSubcategory) return true
    const allowed = meta.appliesWhenSubcategory
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean)
    const sub = (summary.subCategory ?? '').trim().toLowerCase()
    return allowed.length === 0 || allowed.includes(sub)
  }

  const sizeCount = d?.sizes?.length ?? 0
  const variesHere = (key: string, market?: Market) =>
    (d?.perSize?.[key] ?? []).includes(market ?? '*')

  const cellFor = (meta: AttributeMeta, raw: string | undefined, market?: Market) => {
    const value = clean(raw)
    if (!applies(meta)) {
      return {
        state: 'na' as const,
        suspectReason: `Does not apply to ${summary.subCategory || 'this sub-category'}.`,
      }
    }
    if (!value) {
      return detailLoaded
        ? { state: 'missing' as const }
        : {
            state: 'na' as const,
            suspectReason:
              'Detail not loaded for this product — this is not a claim that the value is absent.',
          }
    }
    // The sizes disagree, so there is no option-level value to print. Said
    // rather than shown: the previous behaviour picked whichever size was
    // read first, which for the article code meant a random size's.
    if (variesHere(meta.key, market)) {
      return { state: 'live' as const, perSize: true, sizeCount, code: true }
    }
    const conf = market ? (d?.en?.[meta.key]?.[market] ?? 0) : 0

    // Dropdown terms are stored as Omnitron's default-locale (Turkish) label.
    // Show the market language instead — PL for a shared row, since these
    // values are market-agnostic and one cell has to pick one — and say so
    // when a market has no translation, because the storefront then shows
    // shoppers the Turkish word too.
    const term = labels[meta.key]?.[value]
    const shown = market ? term?.[market] : term?.PL
    const untranslated = term
      ? MARKETS.filter((m) => term[m] && !term[m].translated)
      : []

    return {
      state: market ? (summary.live[market] ? ('live' as const) : ('approved' as const)) : ('live' as const),
      value: shown?.label ?? value,
      code: isCode(meta),
      source: 'omnitron export',
      ...(shown && shown.label !== value
        ? { sourceDetail: `Omnitron term: ${value}` }
        : {}),
      ...(conf > 0
        ? { suspect: 'EN?' as const, suspectReason: englishReason(market!, conf) }
        : untranslated.length
          ? {
              suspect: 'T?' as const,
              suspectReason:
                `Omnitron has no ${untranslated.join(', ')} translation for ` +
                `"${value}", so those markets fall back to Turkish — on the ` +
                'storefront as well as here.',
            }
          : {}),
    }
  }

  // Groups appear in the order their first attribute does, so `display_order`
  // in the registry decides the page layout — identity before content before
  // classification — rather than the alphabet.
  const groupOrder = new Map<string, number>()
  for (const meta of registry) {
    const seen = groupOrder.get(meta.group)
    if (seen === undefined || meta.order < seen) groupOrder.set(meta.group, meta.order)
  }

  const byGroup = new Map<string, AttributeGroup['rows']>()
  for (const meta of [...registry].sort(
    (a, b) =>
      (groupOrder.get(a.group) ?? 0) - (groupOrder.get(b.group) ?? 0) ||
      a.group.localeCompare(b.group) ||
      a.order - b.order,
  )) {
    const values = attrValues[meta.key] ?? {}
    const row: AttributeGroup['rows'][number] = {
      key: meta.key,
      label: meta.label.toLowerCase(),
      owner: meta.owner,
      ...(meta.longText ? { longText: true } : {}),
    }
    if (meta.perMarket) {
      const cells: NonNullable<AttributeGroup['rows'][number]['perMarket']> = {}
      for (const m of MARKETS) {
        cells[m] = withOverlay(
          cellFor(meta, values[m], m),
          overlayFor(meta.key, m),
          overlay ? writable.has(`${meta.key}\u0000${m}`) : undefined,
          proposalFor(meta.key, m),
        )
      }
      row.perMarket = cells
    } else {
      // `*` is the market-agnostic sentinel. Fall back to any single market's
      // value so an attribute mis-keyed upstream still shows rather than
      // reading as missing.
      row.shared = withOverlay(
        cellFor(meta, values['*'] ?? Object.values(values)[0]),
        overlayFor(meta.key, '*'),
        overlay ? writable.has(`${meta.key}\u0000*`) : undefined,
      )
    }
    if (!byGroup.has(meta.group)) byGroup.set(meta.group, [])
    byGroup.get(meta.group)!.push(row)
  }

  const groups: AttributeGroup[] = [...byGroup.entries()].map(([title, rows]) => ({
    title,
    rows,
  }))

  // Real per-size rows now that the generator emits them. Previously empty,
  // because the extract only carried ModelColor-grain values — the size table
  // was the one part of the design with no data behind it at all.
  const sizes: SizeRow[] = (d?.sizes ?? []).map((s) => ({
    label: s.label,
    sku: s.sku,
    ...(s.ean ? { ean: s.ean } : {}),
    stock: s.stock,
    price: s.price,
  }))

  return {
    modelColor,
    name: summary.name,
    baseCode: modelColor.split('.')[0],
    colorCode: modelColor.split('.')[1] ?? '',
    colorName: '',
    season: summary.season,
    gender: summary.gender,
    category: summary.mainCategory,
    subCategory: summary.subCategory,
    sizeCount: summary.skuCount,
    lastChangedAt: summary.lastChangedAt ?? '—',
    lastChangedVia: summary.lastChangedVia ?? 'no Omnitron timestamp',
    markets: MARKETS.map((m) => ({
      market: m,
      // The badge reads from the same source as the sentence beneath it, and
      // in that order of precedence, so the two cannot contradict each other.
      //
      // They could before. The badge took `summary.live` and the sentence took
      // `summary.observed`, and nothing held them together beyond the
      // generator happening to derive one from the other — so any extract
      // where they disagreed rendered a LIVE badge directly above the words
      // "not on sale". A card whose two halves argue is worse than either
      // half being wrong, because the reader cannot tell which to believe.
      live: summary.observed?.[m] ?? summary.live[m] ?? false,
      // Say what was checked, and only that.
      //
      // This sentence claimed the image and ban rules had passed while the
      // generator evaluated neither — so a product with no photo at all read
      // as live in three markets, with the tile asserting the image check
      // passed and the images panel directly below saying it could not go
      // live without one. Five of the six rules are now genuinely evaluated
      // (see `rules/liveness` and the generator), so the claim is true; only
      // category assignment is still unchecked, because it is not synced.
      //
      // `live` and `blockedBy` come from different places — the shop's own
      // listing, and our rules — so the sentence has to say which one it is
      // about. It used to fall back to "all pass" whatever `live` said, which
      // put that sentence under a NOT LIVE badge whenever the rules passed
      // and the shop simply was not listing the option.
      reason: marketReason(summary, m),
    })),
    groups,
    sizes,
    blockers: buildBlockers(summary),
    images: (d?.photos?.length ? d.photos : summary.imageUrl ? [summary.imageUrl] : []).map(
      (url, i) => ({ position: i + 1, url, state: 'live' as const }),
    ),
  }
}

/**
 * The sentence under one market's LIVE / NOT LIVE badge.
 *
 * **Branch on whether we looked at the shop, not on what the rules concluded.**
 * `observed[m]` is present only for markets the storefront crawl reached, and
 * where it is present it is not a prediction — we read the market's own site.
 * So those two branches state a fact and carry no rule talk at all: if the shop
 * is selling it, the product is live, full stop, and a sentence hedging about
 * which internal checks ran only invites the reader to doubt a thing we
 * actually observed.
 *
 * That replaced a sentence reading "Price, stock, image, ban and catalogue all
 * pass. Category assignment is not synced, so it is not checked." — true, and
 * carefully so after an earlier version claimed checks that never ran, but it
 * described our plumbing under a badge whose job is to answer a business
 * question. The caveat it carried belongs to the *derived* case, which is the
 * last branch here and is the only one that says anything tentative.
 *
 * Wording is market-neutral: no "the PL shop", because the card is already
 * headed by the market and the country name is in the tile beside it.
 */
function marketReason(p: ProductSummary, m: Market): string {
  const why = p.blockedBy[m]
  const seen = p.observed?.[m]

  // Seen on sale. Nothing is blocking it, because it already sells.
  if (seen === true) {
    return why
      ? `On sale, but flagged — ${why.toLowerCase()}. Not stopping sales; worth a look.`
      : 'On sale on this market’s website.'
  }

  // Seen absent. A rule that explains it is the useful answer; where every
  // check passes, say exactly which ones did rather than apologising — the
  // reader's next question is "then what is holding it?" and naming the four
  // that are clean is what narrows it.
  if (seen === false) {
    return why
      ? `${why}. Not on sale in this market.`
      : 'Not on sale, although price, stock, images and catalogue are all in place.'
  }

  // No reading of this market's site, so everything here is inferred.
  return why
    ? `${why}. Blocks this market.`
    : 'Every check passes. Not yet confirmed against the website.'
}

/**
 * The blocker rail: what stands between this product and going live, grouped
 * by who can actually do something about it.
 *
 * Ownership comes from the registry's `write_channel`, carried through the
 * extract as `gaps[].owner`. It used to be hardcoded — everything "ours"
 * except a literal check for `Category` — which put the Turkey team's fields
 * (collar type, fit, composition, sub-category) in our queue, and made the
 * "chase only" group almost always empty. Half the point of the rail is
 * knowing which list a gap belongs on.
 */
function buildBlockers(p: ProductSummary): ProductDetail['blockers'] {
  const ours: Array<{ scope: string; text: string }> = []
  const partner: Array<{ scope: string; text: string }> = []
  const system: Array<{ scope: string; text: string }> = []
  const warnings: Array<{ scope: string; text: string }> = []

  for (const m of MARKETS) {
    const why = p.blockedBy[m]
    if (!why) continue
    // Live in the shop while a rule says blocked — banned being the usual
    // case — is a disagreement to look at, not a blocker: nothing is stopping
    // the product going live, because it already is.
    if (p.live[m]) {
      warnings.push({ scope: m, text: `On sale, but flagged — ${why.toLowerCase()}.` })
    } else {
      ours.push({ scope: m, text: `${why}. Blocks ${m} going live.` })
    }
  }
  for (const d of p.defects) ours.push({ scope: 'ALL', text: d })

  for (const gap of p.gaps ?? []) {
    const text = `${gap.label} missing.`
    if (gap.owner === 'partner') partner.push({ scope: gap.scope, text })
    // read_only attributes — price, stock, image — are nobody's to type in.
    // They arrive from a feed, so the honest wording is "waiting", not "todo".
    else if (gap.owner === 'system')
      system.push({ scope: gap.scope, text: `${gap.label} not supplied by the feed.` })
    else ours.push({ scope: gap.scope, text })
  }

  // Older extracts have no `gaps`; keep their price/stock strings readable
  // rather than showing nothing at all.
  if (!p.gaps) {
    for (const miss of p.missing) ours.push({ scope: 'ALL', text: `${miss} missing.` })
  }

  const out: ProductDetail['blockers'] = []
  // Group labels name **who acts**, in the words that person would use. The
  // rail is read by a merchandiser deciding what to do next, so "Nobody —
  // waiting on a feed" (accurate: no human can type a price in) read as an
  // admission that the tool had given up, and "chase only" is our shorthand,
  // not theirs.
  if (ours.length) out.push({ owner: 'us', label: `Ours to fix — ${ours.length}`, items: ours.slice(0, 6) })
  if (partner.length)
    out.push({ owner: 'partner', label: 'Turkey team — ours to chase', items: partner.slice(0, 6) })
  if (system.length)
    out.push({ owner: 'system', label: 'Arrives from the feed — nothing to type', items: system.slice(0, 4) })
  if (!out.length) out.push({ owner: 'nobody', label: 'Nothing blocking', items: [{ scope: 'ALL', text: 'Complete and on sale in every market.' }] })
  if (warnings.length)
    out.push({ owner: 'warning', label: 'Worth a look — on sale despite a flag', items: warnings })
  return out
}
